ALTER TABLE sys_user ADD COLUMN auth_version INT NOT NULL DEFAULT 0;
CREATE TABLE booking_rule(id INT PRIMARY KEY, open_time TIME NOT NULL, close_time TIME NOT NULL, slot_minutes INT NOT NULL, min_advance_hours INT NOT NULL, max_advance_days INT NOT NULL, change_cutoff_hours INT NOT NULL);
INSERT INTO booking_rule VALUES(1,'09:00','20:00',30,2,30,24);
CREATE TABLE service_record(appointment_id BIGINT PRIMARY KEY,checked_in_at DATETIME,started_at DATETIME,completed_at DATETIME,operator_id BIGINT,notes VARCHAR(1000) NOT NULL DEFAULT '',updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(appointment_id) REFERENCES appointment(id));
CREATE TABLE payment_record(id BIGINT PRIMARY KEY AUTO_INCREMENT,appointment_id BIGINT NOT NULL,type VARCHAR(10) NOT NULL,amount DECIMAL(10,2) NOT NULL,method VARCHAR(20) NOT NULL,original_id BIGINT,reason VARCHAR(500) NOT NULL,operator_id BIGINT NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(appointment_id) REFERENCES appointment(id),FOREIGN KEY(original_id) REFERENCES payment_record(id),CHECK(amount>0),INDEX(appointment_id));
CREATE TABLE command_receipt(user_id BIGINT NOT NULL,request_id VARCHAR(64) NOT NULL,fingerprint VARCHAR(64) NOT NULL,PRIMARY KEY(user_id,request_id));
CREATE TABLE customer_request(id BIGINT PRIMARY KEY AUTO_INCREMENT,customer_id BIGINT NOT NULL,appointment_id BIGINT NOT NULL,type VARCHAR(30) NOT NULL,content VARCHAR(1000) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'PENDING',handler_id BIGINT,result VARCHAR(1000) NOT NULL DEFAULT '',version INT NOT NULL DEFAULT 0,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(appointment_id) REFERENCES appointment(id),FOREIGN KEY(customer_id) REFERENCES customer(id),INDEX(customer_id,status));
CREATE TABLE notification(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,type VARCHAR(30) NOT NULL,title VARCHAR(100) NOT NULL,content VARCHAR(1000) NOT NULL,appointment_id BIGINT,read_at DATETIME,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,id));
CREATE TABLE operation_log(id BIGINT PRIMARY KEY AUTO_INCREMENT,operator_id BIGINT NOT NULL,module VARCHAR(40) NOT NULL,action VARCHAR(50) NOT NULL,target_id BIGINT,detail VARCHAR(2000) NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,INDEX(created_at));
